import csv
from collections import defaultdict

data = defaultdict(list)
with open(VALUES_CSV) as f:
    r = csv.DictReader(f)
    for row in r:
        data[row['timeseries_id']].append((row['timestamp'], float(row['value'])))
for tid in data:
    data[tid].sort(key=lambda x: x[0])

f3z01_temp = 'e0dd5f44-f050-5faa-a2a0-a3fcb6284ae8'
