    'F3_Z05': 'c49bbc2f-096e-5e16-bead-066250790308',
    'F4_Z01': '14a08406-79a0-52ca-b8a1-8563259dc820',
    'F4_Z05': None,
}

def monthly(series):
    months = defaultdict(list)
    for ts, v in series:
        months[ts[:7]].append(v)
    return {m: sum(v)/len(v) for m,v in months.items() if len(v)>1}

def std(series):
    vs=[v for _,v in series]
    n=len(vs); m=sum(vs)/n
    var=sum((x-m)**2 for x in vs)/n
    return (var)**0.5

f3z01_m = monthly(data[f3z01_temp])
names = ['F3_Z01','F3_Z02','F3_Z03','F3_Z05','F2_Z01','F2_Z06','F4_Z01']
series_map = {'F3_Z01':data[f3z01_temp],'F3_Z02':data[other_temps['F3_Z02']],'F3_Z03':data[other_temps['F3_Z03']],'F3_Z05':data[other_temps['F3_Z05']],'F2_Z01':data[other_temps['F2_Z01']],'F2_Z06':data[other_temps['F2_Z06']],'F4_Z01':data[other_temps['F4_Z01']]}

def mval(name, mon):
    return monthly(series_map[name]).get(mon, float('nan'))

months = sorted(f3z01_m)
print("Month   " + "  ".join(f"{n:>7}" for n in names))
for m in months:
    row = [f"{m:>8} "]
    for n in names:
        try:
            row.append(f"{mval(n):>7.2f}")
        except:
            row.append(f"{'nan':>7}")
    print(" ".join(row))
